#include <stdio.h>
#include <stdlib.h>

int n;
int *position;
int *column;
int *diag1;
int *diag2;
int first_solution = 1;

void print_solution(void) {
    /* 两个解之间输出一个空行 */
    if (!first_solution) {
        printf("\n");
    }
    first_solution = 0;

    for (int row = 0; row < n; row++) {
        for (int col = 0; col < n; col++) {
            if (position[row] == col) {
                printf("Q");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

void dfs(int row) {
    /* n 行都成功放置，得到一个解 */
    if (row == n) {
        print_solution();
        return;
    }

    /* 从左到右尝试，保证解的输出顺序稳定 */
    for (int col = 0; col < n; col++) {
        int d1 = row + col;
        int d2 = row - col + n;

        if (!column[col] && !diag1[d1] && !diag2[d2]) {
            /* 放置皇后 */
            position[row] = col;
            column[col] = 1;
            diag1[d1] = 1;
            diag2[d2] = 1;

            /* 递归处理下一行 */
            dfs(row + 1);

            /* 回溯，撤销皇后 */
            column[col] = 0;
            diag1[d1] = 0;
            diag2[d2] = 0;
        }
    }
}

int main(void) {
    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    position = (int *)malloc((size_t)n * sizeof(int));
    column = (int *)calloc((size_t)n, sizeof(int));
    diag1 = (int *)calloc((size_t)(2 * n + 1), sizeof(int));
    diag2 = (int *)calloc((size_t)(2 * n + 1), sizeof(int));

    if (position == NULL || column == NULL ||
        diag1 == NULL || diag2 == NULL) {
        free(position);
        free(column);
        free(diag1);
        free(diag2);
        return 0;
    }

    dfs(0);

    free(position);
    free(column);
    free(diag1);
    free(diag2);

    return 0;
}
